const PF2E_ANCESTRIES = {
  "catfolk": {"n":"Catfolk","hp":8,"sz":"med","sp":25,"bo":[["cha"],["dex"],["free"]],"fl":["wis"],"la":["amurrun","common"],"lo":["draconic","elven","fey","gnomish","goblin","halfling","iruxi","jotun"],"vi":"low-light-vision","tr":["catfolk","humanoid"],"f":[["Land on Your Feet","When you fall, you take only half the normal damage and don't land Prone."]],"ra":"u","b":"PC2"},
  "dwarf": {"n":"Dwarf","hp":10,"sz":"med","sp":20,"bo":[["con"],["wis"],["free"]],"fl":["cha"],"la":["common","dwarven"],"lo":["gnomish","goblin","jotun","orcish","petran","sakvroth"],"vi":"darkvision","tr":["dwarf","humanoid"],"f":[["Clan Dagger","You get one Clan Dagger of your clan for free, as it was given to you at birth. Selling this dagger is a terrible taboo and earns you the disdain of other dwarves."]],"b":"PC"},
  "elf": {"n":"Elf","hp":6,"sz":"med","sp":30,"bo":[["dex"],["int"],["free"]],"fl":["con"],"la":["common","elven"],"lo":["draconic","empyrean","fey","gnomish","goblin","kholo","orcish"],"vi":"low-light-vision","tr":["elf","humanoid"],"b":"PC"},
  "gnome": {"n":"Gnome","hp":8,"sz":"sm","sp":25,"bo":[["cha"],["con"],["free"]],"fl":["str"],"la":["common","fey","gnomish"],"lo":["draconic","dwarven","elven","goblin","jotun","orcish"],"vi":"low-light-vision","tr":["gnome","humanoid"],"b":"PC"},
  "goblin": {"n":"Goblin","hp":6,"sz":"sm","sp":25,"bo":[["cha"],["dex"],["free"]],"fl":["wis"],"la":["common","goblin"],"lo":["draconic","dwarven","gnomish","halfling","kholo","orcish"],"vi":"darkvision","tr":["goblin","humanoid"],"b":"PC"},
  "halfling": {"n":"Halfling","hp":6,"sz":"sm","sp":25,"bo":[["dex"],["wis"],["free"]],"fl":["str"],"la":["common","halfling"],"lo":["dwarven","elven","gnomish","goblin"],"tr":["halfling","humanoid"],"f":[["Keen Eyes","Your eyes are sharp, allowing you to make out small details about Concealed or even Invisible creatures that others might miss. You gain a +2 circumstance bonus when using the Seek action to find Hidden or Undetected creatures within 30 feet of you. When you target an opponent that is concealed from you or hidden from you, reduce the DC of the flat check to 3 for a concealed target or 9 for a hidden one."]],"b":"PC"},
  "hobgoblin": {"n":"Hobgoblin","hp":8,"sz":"med","sp":25,"bo":[["con"],["int"],["free"]],"fl":["wis"],"la":["common","goblin"],"lo":["draconic","dwarven","halfling","jotun","kholo","orcish"],"vi":"darkvision","tr":["hobgoblin","humanoid"],"ra":"u","b":"PC2"},
  "human": {"n":"Human","hp":8,"sz":"med","sp":25,"bo":[["free"],["free"]],"la":["common"],"lo":[],"lc":1,"tr":["human","humanoid"],"b":"PC"},
  "kholo": {"n":"Kholo","hp":8,"sz":"med","sp":25,"bo":[["str"],["int"],["free"]],"fl":["wis"],"la":["common","kholo"],"lo":["draconic","elven","fey","iruxi","necril","orcish"],"vi":"low-light-vision","tr":["humanoid","kholo"],"f":[["Bite","Your sharp teeth and powerful jaws are fearsome weapons. You have a jaws unarmed attack that deals 1d6 piercing damage. Your jaws are in the brawling group."]],"ra":"u","b":"PC2"},
  "kobold": {"n":"Kobold","hp":6,"sz":"sm","sp":25,"bo":[["cha"],["dex"],["free"]],"fl":["con"],"la":["common","sakvroth"],"lo":["aklo","diabolic","draconic","dwarven","empyrean","fey","gnomish","petran"],"vi":"darkvision","tr":["humanoid","kobold"],"ra":"u","b":"PC2"},
  "leshy": {"n":"Leshy","hp":8,"sz":"sm","sp":25,"bo":[["con"],["wis"],["free"]],"fl":["int"],"la":["common","fey"],"lo":["draconic","elven","gnomish","goblin","halfling","sakvroth"],"vi":"low-light-vision","tr":["leshy","plant"],"f":[["Plant Nourishment","You gain nourishment in the same way that the plants or fungi that match your body type normally do, through some combination of photosynthesis, absorbing minerals with your roots, or scavenging decaying matter. You typically do not need to pay for food. If you normally rely on photosynthesis and go without sunlight for 1 week, you begin to starve. You can derive nourishment from specially formulated bottles of sunlight instead of natural sunlight, but these bottles cost 10 times as much as standard rations (or 40 sp)."]],"b":"PC"},
  "lizardfolk": {"n":"Lizardfolk","hp":8,"sz":"med","sp":25,"bo":[["str"],["wis"],["free"]],"fl":["int"],"la":["common","iruxi"],"lo":["amurrun","boggard","draconic","elven","fey","jotun","thalassic"],"tr":["humanoid","lizardfolk"],"f":[["Aquatic Adaptation","Your reptilian biology allows you to hold your breath for a long time. You gain the Breath Control general feat as a bonus feat."],["Claws","Your sharp claws offer an alternative to the fists other humanoids bring to a fight. You have a claw unarmed attack that deals 1d4 slashing damage and has the agile and finesse traits."]],"ra":"u","b":"PC2"},
  "orc": {"n":"Orc","hp":10,"sz":"med","sp":25,"bo":[["free"],["free"]],"la":["common","orcish"],"lo":["goblin","jotun","petran","sakvroth"],"vi":"darkvision","tr":["humanoid","orc"],"b":"PC"},
  "ratfolk": {"n":"Ratfolk","hp":6,"sz":"sm","sp":25,"bo":[["dex"],["int"],["free"]],"fl":["str"],"la":["common","ysoki"],"lo":["aklo","draconic","dwarven","gnomish","goblin","halfling","kholo","orcish","sakvroth"],"vi":"low-light-vision","tr":["humanoid","ratfolk"],"f":[["Sharp Teeth","Your prominent incisors offer an alternative to the fists other humanoids bring to a fight. You have a jaws unarmed attack that deals 1d4 piercing damage, is in the brawling group, and has the agile and finesse traits."]],"ra":"u","b":"PC2"},
  "tengu": {"n":"Tengu","hp":6,"sz":"med","sp":25,"bo":[["dex"],["free"]],"la":["common","tengu"],"lo":["dwarven","elven","fey","gnomish","goblin","halfling"],"vi":"low-light-vision","tr":["humanoid","tengu"],"f":[["Sharp Beak","With your sharp beak, you are never without a weapon. You have a beak unarmed attack that deals 1d6 piercing damage. Your beak is in the brawling weapon group and has the finesse and unarmed traits."]],"ra":"u","b":"PC2"},
  "tripkee": {"n":"Tripkee","hp":6,"sz":"sm","sp":25,"bo":[["dex"],["wis"],["free"]],"fl":["str"],"la":["common","tripkee"],"lo":["boggard","chthonian","draconic","elven","fey","iruxi","thalassic"],"vi":"low-light-vision","tr":["humanoid","tripkee"],"f":[["Natural Climber","You gain a +2 circumstance bonus to Athletics checks to Climb."]],"ra":"u","b":"PC2"}
};

const PF2E_HERITAGES = {
  "aiuvarin": {"n":"Aiuvarin","a":"","x":"You have elves, or possibly other aiuvarins, in your family tree. You have pointed ears and other telltale signs of elf heritage. You gain the elf trait, the aiuvarin trait, and low-light vision. In addition, when you gain an ancestry feat, you can choose from aiuvarin and elf feats in addition to those from your ancestry.","tr":["aiuvarin"],"b":"PC"},
  "ancient-blooded-dwarf": {"n":"Ancient-Blooded Dwarf","a":"dwarf","x":"Dwarven heroes of old could shrug off their enemies' magic, and some of that resistance manifests in you. You gain the Call on Ancient Blood reaction.","b":"PC"},
  "ancient-elf": {"n":"Ancient Elf","a":"elf","x":"In your long life, you've dabbled in many paths and many styles. A typical ancient elf is at least 100 years old, though you might be younger at the GM's discretion. Choose a class other than your own. You gain the multiclass dedication feat for that class, even though you don't meet its level prerequisite. You must still meet its other prerequisites to gain the feat.","b":"PC"},
  "ant-kholo": {"n":"Ant Kholo","a":"kholo","x":"You're a sharp-featured, big-eared kholo about 3 feet tall. Many are skeptical that you are in fact a kholo. Your size is Small instead of Medium. You are trained in Deception (or another skill if you were already trained in Deception). You gain a +1 circumstance bonus to Deception checks to Lie when specifically claiming innocence, to Deception DCs against Sense Motive checks to uncover such lies, and to initiative checks when you roll Deception for initiative.","b":"PC2"},
  "arctic-elf": {"n":"Arctic Elf","a":"elf","x":"You dwell deep in the frozen north and have gained incredible resilience against cold environments, granting you cold resistance equal to half your level (minimum 1). You treat environmental cold effects as if they were one step less extreme (incredible cold becomes extreme, extreme cold becomes severe, and so on).","b":"PC"},
  "badlands-orc": {"n":"Badlands Orc","a":"orc","x":"You come from sun-scorched badlands, where long legs and an ability to withstand the elements helped you thrive. You can Hustle twice as long while exploring before you have to stop, and you treat environmental heat effects as if they were one step less extreme (incredible heat becomes extreme, extreme heat becomes severe, and so on).","b":"PC"},
  "battle-ready-orc": {"n":"Battle-Ready Orc","a":"orc","x":"You descend from a line of terrifying battlefield commanders. You become trained in Intimidation, and you gain the Intimidating Glare skill feat.","b":"PC"},
  "cactus-leshy": {"n":"Cactus Leshy","a":"leshy","x":"Spines cover your body. You gain a spine unarmed attack that deals 1d6 piercing damage. Your spines are in the brawling group and have the finesse and unarmed traits.","b":"PC"},
  "cave-kholo": {"n":"Cave Kholo","a":"kholo","x":"Storytellers spin ancient tales claiming that kholo lived in caves and underground before most of your kind ventured into the light. You're a throwback to these ancients, with a broad chest and markings that resemble short black slashes instead of spots. Your eyes are developed to see perfectly in the dark, a valuable advantage to your clan. You gain darkvision.","b":"PC2"},
  "cavern-elf": {"n":"Cavern Elf","a":"elf","x":"You were born or spent many years in underground tunnels or caverns where light is scarce. You gain darkvision.","b":"PC"},
  "cavernstalker-kobold": {"n":"Cavernstalker Kobold","a":"kobold","x":"You hatched in a warren with narrow tunnels that was also home to a being of primal earth energy, which has made you limber and flexible. When Climbing rock walls, stalactites, and other natural stone features, you move at half your Speed on a success and at full Speed on a critical success (and you move at full Speed on a success if you have Quick Climb). This doesn't affect you if you're using a climb Speed. If you roll a success on an Acrobatics check to Squeeze, you get a critical success instead.","b":"PC2"},
  "chameleon-gnome": {"n":"Chameleon Gnome","a":"gnome","x":"The color of your hair and skin is mutable, possibly due to latent magic from First World influences or lingering illusion effects. You can slowly change the vibrancy and the exact color, and the coloration can be different across your body, allowing you to create patterns or other colorful designs. It takes a single action for minor localized shifts and up to an hour for dramatic shifts throughout your body. While you're asleep, the colors shift on their own in tune with your dreams, giving you an unusual coloration each morning. When you're in an area where your coloration is roughly similar to the environment (for instance, forest green in a forest), you can use the single action to make minor localized shifts designed to help you blend into your surroundings. This grants you a +2 circumstance bonus to Stealth checks until your surroundings shift in coloration or pattern.","b":"PC"},
  "changeling": {"n":"Changeling","a":"","x":"Your mother was a hag. Your eyes' heterochromia is the most obvious signifier of this parentage, but you likely also have a slighter build, paler skin, and darker hair than most members of your other parent's ancestry. You gain the changeling trait. You also gain low-light vision, or you gain darkvision if your ancestry already has low-light vision. You can select from changeling feats and feats from your other parent's ancestry whenever you gain an ancestry feat.","tr":["changeling"],"ra":"u","b":"PC"},
  "charhide-goblin": {"n":"Charhide Goblin","a":"goblin","x":"Your ancestors have always had a connection to fire and a thicker skin, which allows you to resist burning. You gain fire resistance equal to half your level (minimum 1). You can also recover from being on fire more easily. Your flat check to remove persistent fire damage is DC 10 instead of DC 15, which is reduced to DC 5 flat check if another creature uses a particularly appropriate action to help.","b":"PC"},
  "clawed-catfolk": {"n":"Clawed Catfolk","a":"catfolk","x":"Your family has particularly long, sharp claws capable of delivering bleeding wounds with a wicked swipe. You gain a claw unarmed attack that deals 1d6 slashing damage. Your claws are in the brawling group and have the agile, finesse and unarmed traits.","b":"PC2"},
  "cliffscale-lizardfolk": {"n":"Cliffscale Lizardfolk","a":"lizardfolk","x":"Your toes are adapted for gripping and climbing. You gain the Combat Climber feat as a bonus feat, and as long as you aren't wearing footwear, you can use the sticky pads on your feet to climb, leaving your hands free. Additionally, if you roll a success on an Athletics check to climb, you get a critical success instead.","b":"PC2"},
  "cloudleaper-lizardfolk": {"n":"Cloudleaper Lizardfolk","a":"lizardfolk","x":"Your body is light with flaps of skin along your limbs that catch the air that passes beneath you. As long as you can act and have enough room, you can open the flaps to slow any fall just enough to avoid taking damage (whether you have the room to do so depends on the GM's discretion).","b":"PC2"},
  "death-warden-dwarf": {"n":"Death Warden Dwarf","a":"dwarf","x":"Your ancestors were tomb guardians, and their power to ward off death passed on to you. If you roll a success on a saving throw against an effect that has the void trait or was created by an undead creature, you get a critical success instead.","b":"PC"},
  "deep-orc": {"n":"Deep Orc","a":"orc","x":"Your calloused hands and red eyes speak to a life spent in the deep darkness of mountain caverns, where you learned to battle on rocky cliffs and survive with minimal resources. You gain the Terrain Expertise skill feat for underground terrain and the Combat Climber skill feat.","b":"PC"},
  "deep-rat": {"n":"Deep Rat","a":"ratfolk","x":"Your ancestors lived deeper underground than other ratfolk, granting you the ability to see in the dark. You gain darkvision.","b":"PC2"},
  "desert-rat": {"n":"Desert Rat","a":"ratfolk","x":"You are native to arid plains and likely grew up traveling the roads. If you have both hands free, you can increase your Speed to 30 feet as you run on all fours. In addition, environmental heat effects are one step less extreme for you, and you can go 10 times longer than normal before you are affected by starvation or thirst. However, unless you wear protective gear or take shelter, environmental cold effects are one step more extreme for you.","b":"PC2"},
  "dhampir": {"n":"Dhampir","a":"","x":"You are the scion of a vampire, half living and half undead, gifted with uncanny charm and grace, a bloodless pallor, and elongated incisors. You gain the dhampir trait, in addition to the traits from your ancestry. You have the void healing ability, which means you are harmed by vitality damage and healed by void effects as if you were undead. You also gain low-light vision, or you gain darkvision if your ancestry already has low-light vision. You can select from dhampir feats and feats from your ancestry whenever you gain an ancestry feat.","tr":["dhampir"],"ra":"u","b":"PC2"},
  "dog-kholo": {"n":"Dog Kholo","a":"kholo","x":"You're a nimble-bodied kholo with a prehistoric, almost dog-like build. Though you typically move like a quadruped, you can still stand and fight like a biped, allowing you to use all equipment normally. If you have both hands free, you can increase your Speed to 30 feet as you run on all fours.","b":"PC2"},
  "dogtooth-tengu": {"n":"Dogtooth Tengu","a":"tengu","x":"In addition to a beak, your mouth also features a number of vicious, pointed teeth. Some legends claim your powerful jaws can even bite through steel. While you aren't that strong yet, your fangs can still leave terrible wounds. Your beak unarmed attack gains the deadly d8 trait.","b":"PC2"},
  "dragonblood": {"n":"Dragonblood","a":"","x":"You're descended in some way from a dragon. Your physical features might show this outwardly, with a pair of draconic horns, patches of scaly skin, or even a tail, or you might develop an internal reserve of draconic power. You gain the dragonblood trait, in addition to the traits from your ancestry. Add Draconic to your ancestry's list of additional languages (allowing you to choose it as a language if your Intelligence modifier is positive). When you roll a success on a saving throw against a fear effect, you get a critical success instead. You can choose from dragonblood feats and feats from your ancestry whenever you gain an ancestry feat.","tr":["dragonblood"],"ra":"u","b":"PC2"},
  "dragonscaled-kobold": {"n":"Dragonscaled Kobold","a":"kobold","x":"Thanks to your warren's association with a dragon, your scales are sturdier than other kobolds'. You gain 10 Hit Points from your ancestry instead of 6. You gain a +1 circumstance bonus to saves against dragon breath, effects with the sleep trait, and effects that would make you Paralyzed.","b":"PC2"},
  "dromaar": {"n":"Dromaar","a":"","x":"Orcish strength emboldens your bloodline. You have a green tinge to your skin and other indicators of orc heritage. You gain the orc trait, the dromaar trait, and low-light vision. When you gain an ancestry feat, you can choose from dromaar and orc feats in addition to those from your ancestry.","tr":["dromaar"],"b":"PC"},
  "duskwalker": {"n":"Duskwalker","a":"","x":"Thanks to an ancient bargain, your soul has been reborn as a duskwalker, a planar scion with a connection to psychopomps and the Boneyard. You gain the duskwalker trait. You also gain low-light vision, or you gain darkvision if your ancestry already has low-light vision. Neither your body nor your spirit can ever become undead. You can select from duskwalker feats and feats from your ancestry whenever you gain an ancestry feat.","tr":["duskwalker"],"ra":"u","b":"PC2"},
  "elementheart-kobold": {"n":"Elementheart Kobold","a":"kobold","x":"When you hatched, you imprinted on a creature strongly associated with one of the Elemental Planes, such as an elemental or genie. Choose air, earth, fire, metal, water, or wood for your elemental benefactor. You gain resistance equal to half your level (minimum 1) to the damage type associated with your elemental benefactor: cold for air, electricity for earth, fire for fire, sonic for metal, acid for water, or poison for wood.","b":"PC2"},
  "elfbane-hobgoblin": {"n":"Elfbane Hobgoblin","a":"hobgoblin","x":"Hobgoblins were engineered long ago from the unreliable and fecund goblins to be used as an army against the elves. Although the elves ultimately freed the hobgoblins from their bondage, some hobgoblins retain ancestral resistance to magic, which they refer to as \"elf magic.\" You gain the Resist Elf Magic reaction.","b":"PC2"},
  "fey-touched-gnome": {"n":"Fey-Touched Gnome","a":"gnome","x":"The blood of the fey flows through your veins, saturating you with their magic and making you truly one of them. You gain the fey trait, in addition to the gnome and humanoid traits. Choose one cantrip from the primal spell list. You can cast this spell as a primal innate spell at will. A cantrip is heightened to a spell rank equal to half your level rounded up. You can change this cantrip to a different one from the same list once per day by meditating to realign yourself with the First World; this is a 10-minute activity that has the concentrate trait.","b":"PC"},
  "forge-dwarf": {"n":"Forge Dwarf","a":"dwarf","x":"You have a remarkable adaptation to hot environments. This grants you fire resistance equal to half your level (minimum 1), and you treat environmental heat effects as if they were one step less extreme (incredible heat becomes extreme, extreme heat becomes severe, and so on).","b":"PC"},
  "frilled-lizardfolk": {"n":"Frilled Lizardfolk","a":"lizardfolk","x":"You can flare your neck frill and flex your dorsal spines, Demoralizing your foes. When you do, Demoralize loses the auditory trait and gains the visual trait, and you don't take a penalty when you attempt to Demoralize a creature that doesn't understand your language. You also gain the Threatening Approach action.","b":"PC2"},
  "fruit-leshy": {"n":"Fruit Leshy","a":"leshy","x":"Your body continually produces small fruits imbued with primal magic. At dawn each day, a new fruit ripens. You or an ally can remove this fruit as an Interact action. If a living creature that can derive sustenance from fruit consumes it as an Interact action within the next hour, they regain ceil(@actor.level/2))d8 vitality healing Hit Points, plus an additional 1d8 Hit Points for every 2 of your levels beyond 1st. This effect has the healing and vitality traits.","b":"PC"},
  "fungus-leshy": {"n":"Fungus Leshy","a":"leshy","x":"Your body was made from fungi that grows in the shade of caves and trees, and you are at home in dark caverns and warrens. You gain darkvision. You lose the plant trait and gain the fungus trait.","b":"PC"},
  "gourd-leshy": {"n":"Gourd Leshy","a":"leshy","x":"You have a large gourd for a skull, and since you don't have a physical brain, you can use the space inside your head. You can store a collection of up to 1 Bulk of objects within your head. The DC of checks to Steal objects from inside your head increases by 4. Additionally, if you store only one object within your head, you can draw it effortlessly into your hand as part of another action to use the object. Drawing the item grants this other action the manipulate trait.","b":"PC"},
  "grave-orc": {"n":"Grave Orc","a":"orc","x":"You were exposed to powerful necromantic energies that should have killed you—but you survived. Your skin is cold, clammy, and gray. You gain resistance to void damage equal to half your level (minimum 1). You also gain a +1 circumstance bonus to saving throws against effects with the death or void trait.","b":"PC"},
  "great-kholo": {"n":"Great Kholo","a":"kholo","x":"You're an imposing, powerful kholo, with tawny fur and brown spots on your hide. You gain 10 Hit Points from your ancestry instead of 8 and gain a +1 circumstance bonus to Athletics checks to Reposition, Shove, or Trip.","b":"PC2"},
  "gutsy-halfling": {"n":"Gutsy Halfling","a":"halfling","x":"Your family line is known for keeping a level head and staving off fear when the chips were down. When you roll a success on a saving throw against an emotion effect, you get a critical success instead.","b":"PC"},
  "hillock-halfling": {"n":"Hillock Halfling","a":"halfling","x":"Accustomed to a calm life in the hills, your people find rest and relaxation especially replenishing, particularly when indulging in creature comforts. When you regain Hit Points overnight, add your level to the Hit Points regained. When anyone uses the Medicine skill to Treat your Wounds, you can eat a snack to add your level to the Hit Points you regain from their treatment.","b":"PC"},
  "hold-scarred-orc": {"n":"Hold-Scarred Orc","a":"orc","x":"You are part of an orc community that participates in ritual scarification or tattooing. The marks on your skin show your exceptional hardiness and vitality. You gain 12 Hit Points from your ancestry instead of 10. You also gain the Diehard feat.","b":"PC"},
  "hunting-catfolk": {"n":"Hunting Catfolk","a":"catfolk","x":"You come from a long line of skilled hunters and trackers and have a particularly keen sense of smell. You gain imprecise scent with a range of 30 feet. This means you can use your sense of smell to determine a creature's location. The GM will usually double the range if you're downwind from the creature or halve the range if you're upwind.\nIn addition, you gain a +2 circumstance bonus to Track a creature or object if you've smelled it before.","b":"PC2"},
  "irongut-goblin": {"n":"Irongut Goblin","a":"goblin","x":"You can subsist on food that most folks would consider spoiled. You can keep yourself fed with poor meals in a settlement as long as garbage is readily available, without using the Subsist downtime activity. You can eat and drink things when you are Sickened.\nYou gain a +2 circumstance bonus to saving throws against afflictions, against gaining the sickened condition, and to remove the sickened condition. When you roll a success on a Fortitude save affected by this bonus, you get a critical success instead. All these benefits apply only when the affliction or condition resulted from something you ingested.","b":"PC"},
  "jinxed-halfling": {"n":"Jinxed Halfling","a":"halfling","x":"You were born with a strange blessing: bereft of the typical halfling luck, you can instead manipulate the fortunes of others. You can never take the Halfling Luck feat, and you gain the Jinx action.","ra":"u","b":"PC"},
  "jinxed-tengu": {"n":"Jinxed Tengu","a":"tengu","x":"Your lineage has been exposed to curse after curse, and now they slide off your feathers like rain. If you succeed at a saving throw against a curse or misfortune effect, you get a critical success instead. When you would gain the Doomed condition, attempt a DC 17 flat check. On a success, reduce the value of the doomed condition you would gain by 1.","b":"PC2"},
  "jungle-catfolk": {"n":"Jungle Catfolk","a":"catfolk","x":"You're descended from jungle stalkers and can move swiftly through scrub and underbrush. You ignore difficult terrain from undergrowth, and greater difficult terrain from undergrowth is only difficult terrain for you.","b":"PC2"},
  "leaf-leshy": {"n":"Leaf Leshy","a":"leshy","x":"Your body is made mostly from natural foliage, and like a leaf tumbling from a tree, you land from falls with particular grace. You take no damage from falling, regardless of the distance you fall.","b":"PC"},
  "liminal-catfolk": {"n":"Liminal Catfolk","a":"catfolk","x":"You've inherited a closeness to the far corners of the world, where the boundaries between dimensions grow thin. You can cast the Detect Magic cantrip as an occult innate spell at will. A cantrip is heightened to half your level rounded up. You also gain a +1 circumstance bonus to Occultism checks to Recall Knowledge about creatures that originated on planes other than the Universe.","b":"PC2"},
  "longsnout-rat": {"n":"Longsnout Rat","a":"ratfolk","x":"Your long snout gives you a keener sense of smell than most ratfolk. You gain imprecise scent with a range of 30 feet. This means you can use your sense of smell to determine a creature's location. The GM will usually double the range if you're downwind from the creature or halve the range if you're upwind.\nIn addition, you gain a +2 circumstance bonus to Perception checks to Seek a creature or object within the range of your scent.","b":"PC2"},
  "lotus-leshy": {"n":"Lotus Leshy","a":"leshy","x":"You effortlessly float on the surface of water. You can walk on the surface of still water and other non-damaging liquids, moving at half your normal Speed. You can also attempt to Balance to move across the surface of flowing water, using the DC of a Swim check to move through the water. When you do this, you can't move faster than half your Speed, and if you fail or critically fail, you fall into the water rather than the normal effects.","b":"PC"},
  "mountainkeeper-tengu": {"n":"Mountainkeeper Tengu","a":"tengu","x":"You come from a line of tengu ascetics, leaving you with a link to the spirits of the world and the Great Beyond. You can cast the Vitality Lash cantrip as a primal innate spell at will. A cantrip is heightened to a spell rank equal to half your level rounded up. Each time you cast a spell from a tengu heritage or ancestry feat, you can decide whether it's a divine or primal spell.","b":"PC2"},
  "nephilim": {"n":"Nephilim","a":"","x":"Your nature is influenced by celestials, fiends, or monitors. This manifests as a combination of features that belie your heritage, such as golden eyes, a halo, horns, or a tail. You gain the nephilim trait, in addition to the traits from your ancestry. You gain low-light vision, or you gain darkvision if your ancestry already has low-light vision. You can choose from nephilim feats and feats from your ancestry whenever you gain an ancestry feat.","tr":["nephilim"],"ra":"u","b":"PC"},
  "nine-lives-catfolk": {"n":"Nine Lives Catfolk","a":"catfolk","x":"Your family has always seems to bounce back from disaster, not through physical hardiness or specialized skill, but from sheer luck. Other catfolk whisper that you have nine lives. While you're Dying, you don't add your dying value to the DC of your recovery checks (this means the DC is typically 10). In addition, you gain the Diehard general feat.","b":"PC2"},
  "nomadic-halfling": {"n":"Nomadic Halfling","a":"halfling","x":"Your ancestors have traveled from place to place for generations, never content to settle down. You gain two additional languages of your choice, chosen from among the common and uncommon languages available to you, and every time you take the Multilingual feat, you gain another new language.","b":"PC"},
  "poisonhide-tripkee": {"n":"Poisonhide Tripkee","a":"tripkee","x":"You may be small, but the poison glands concealed across your body hide a deadly defense. You gain the Toxic Skin reaction.","b":"PC2"},
  "rainfall-orc": {"n":"Rainfall Orc","a":"orc","x":"You were born in a rain forest with only tangles of trees providing protection from torrential rainstorms and flash floods. You've learned to move adeptly through jungle terrain and resist the various ailments common in humid environs. You gain a +2 circumstance bonus to Athletics checks to Climb or Swim and a +1 circumstance bonus to saving throws against diseases.","b":"PC"},
  "razortooth-goblin": {"n":"Razortooth Goblin","a":"goblin","x":"Your family's teeth are formidable weapons. You gain a jaws unarmed attack that deals 1d6 piercing damage. Your jaws are in the brawling group and have the finesse and unarmed traits.","b":"PC"},
  "riverside-tripkee": {"n":"Riverside Tripkee","a":"tripkee","x":"Your ancestors live in and on the water. You gain a 15-foot swim Speed.","b":"PC2"},
  "rock-dwarf": {"n":"Rock Dwarf","a":"dwarf","x":"Your ancestors lived and worked among the ancient stones of the mountains or the depths of the earth. This makes you solid as a rock when you plant your feet. You gain a +2 circumstance bonus to your Fortitude or Reflex DC against attempts to Reposition, Shove, or Trip you. This bonus also applies to saving throws against spells or effects that attempt to force you to move or knock you Prone.\nIn addition, if any effect would force you to move 10 feet or more, you are moved only half the distance.","b":"PC"},
  "root-leshy": {"n":"Root Leshy","a":"leshy","x":"Your body is made from hardy roots that attach you firmly to the ground. You gain 10 Hit Points from your ancestry instead of 8. You can go without sunlight for 2 weeks before you begin to starve. You gain a +2 circumstance bonus to your Fortitude or Reflex DC against attempts to Reposition, Shove, or Trip you. This bonus also applies to saving throws against spells or effects that attempt to move you or knock you Prone.","b":"PC"},
  "runtboss-hobgoblin": {"n":"Runtboss Hobgoblin","a":"hobgoblin","x":"You come from a long line of hobgoblins who commanded goblins. You are smaller than other hobgoblins, but goblins still listen to any commands you bellow. You gain the Group Coercion skill feat. If you roll a success on an Intimidation check to Coerce a goblin, you get a critical success instead; if you roll a critical failure, you get a failure instead.","b":"PC2"},
  "sandstrider-lizardfolk": {"n":"Sandstrider Lizardfolk","a":"lizardfolk","x":"Your thick scales help you retain water and combat the sun's glare. You gain fire resistance equal to half your level (minimum 1). Environmental heat effects are one step less extreme for you, and you can go 10 times as long as normal before you are affected by starvation or thirst. However, unless you wear protective gear or take shelter, environmental cold effects are one step more extreme for you.","b":"PC2"},
  "seaweed-leshy": {"n":"Seaweed Leshy","a":"leshy","x":"Your body is made from woven seaweed, and you're just as comfortable underwater as on land. You gain a swim Speed of 20 feet, and you can always breathe underwater. However, your land Speed is reduced by 5 feet (to 20 feet for most seaweed leshies).","b":"PC"},
  "seer-elf": {"n":"Seer Elf","a":"elf","x":"You have an inborn ability to detect and understand magical phenomena. You can cast the Detect Magic cantrip as an arcane innate spell at will. A cantrip is heightened to a spell rank equal to half your level rounded up.\nIn addition, you gain a +1 circumstance bonus to checks to Identify Magic and to Decipher Writing of a magical nature. These skill actions typically use the Arcana, Nature, Occultism, or Religion skill.","b":"PC"},
  "sensate-gnome": {"n":"Sensate Gnome","a":"gnome","x":"You see all colors as brighter, hear all sounds as richer, and especially smell all scents with incredible detail. You gain a special sense: imprecise scent with a range of 30 feet. This means you can use your sense of smell to determine the exact location of a creature. The GM will usually double the range if you're downwind from the creature or halve the range if you're upwind.\nIn addition, you gain a +2 circumstance bonus to Perception checks whenever you're trying to locate an undetected creature that is within the range of your scent.","b":"PC"},
  "sewer-rat": {"n":"Sewer Rat","a":"ratfolk","x":"You come from a long line of ratfolk with a community based in the sewers beneath a large settlement. You are immune to the disease putrid plague. You gain a +1 circumstance bonus to saving throws against diseases and poisons. If you roll a success on a saving throw against a disease or poison, you get a critical success instead. If you have a different ability that would improve the save in this way (such as the Battle Hardened fighter class feature), if you roll a critical failure on the save you get a failure instead.","b":"PC2"},
  "shadow-rat": {"n":"Shadow Rat","a":"ratfolk","x":"Your ancestors lived in dark spaces underground, granting you dark fur and a vaguely unnatural mien. You gain the trained proficiency rank in Intimidation and can use Intimidation to Coerce animals. When you Demoralize an animal, you don't take a penalty for not sharing a language with it. If you would automatically become trained in Intimidation (from your background or class, for example), you become trained in another skill of your choice.\nAnimals' attitudes toward you begin one degree worse than normal, usually starting at unfriendly instead of indifferent for domesticated animals, and hostile instead of unfriendly for wild animals.","b":"PC2"},
  "sharp-eared-catfolk": {"n":"Sharp-Eared Catfolk","a":"catfolk","x":"You were born with big, expressive ears that move with your moods and perk up at any unexpected sound. You gain a +2 circumstance bonus to locate undetected creatures that you could hear within 30 feet with a Seek action. As long as you're aware of a creature via sound, once per round, your ears can help you Point Out the creature to all allies as a free action.","b":"PC2"},
  "shortshanks-hobgoblin": {"n":"Shortshanks Hobgoblin","a":"hobgoblin","x":"You have a longer torso and broader shoulders than most hobgoblins, making your legs seem short by comparison. This gives you a strong, muscular core and lowers your center of gravity—features that assist you in riding and climbing—and you've trained at riding in a saddle from an extremely early age. You gain the Ride feat. Additionally, you are not Off-Guard while you Climb.","b":"PC2"},
  "skilled-human": {"n":"Skilled Human","a":"human","x":"Your ingenuity allows you to train in a wide variety of skills. You become trained in one skill of your choice. At 5th level, you become an expert in the chosen skill.","b":"PC"},
  "skyborn-tengu": {"n":"Skyborn Tengu","a":"tengu","x":"Your bones may be especially light, you may be a rare tengu with wings, or your connection to the spirits of wind and sky might be stronger than most, slowing your descent through the air. You take no damage from falling, regardless of the distance you fall.","b":"PC2"},
  "smokeworker-hobgoblin": {"n":"Smokeworker Hobgoblin","a":"hobgoblin","x":"Your family have been alchemists, engineers, and scientists for generations, laboring on projects that bring smoke and fire to the field of battle. You gain fire resistance equal to half your level (minimum 1). You automatically succeed at the DC 5 flat check to target a Concealed creature if that creature is concealed only by smoke.","b":"PC2"},
  "snaptongue-tripkee": {"n":"Snaptongue Tripkee","a":"tripkee","x":"Your tongue is especially long, and you can launch it with extraordinary range and precision. You can use your tongue to deliver spells with a range of touch and perform extremely simple Interact actions, such as opening some types of unlocked doors. Your tongue can't perform actions that require fingers or significant manual dexterity, including any action that would require a check to accomplish, and you can't use it to hold items.","b":"PC2"},
  "snow-goblin": {"n":"Snow Goblin","a":"goblin","x":"You are acclimated to living in frigid lands and have skin ranging from sky blue to navy in color, as well as blue fur. You gain cold resistance equal to half your level (minimum 1). You treat environmental cold effects as if they were one step less extreme (incredible cold becomes extreme, extreme cold becomes severe, and so on).","b":"PC"},
  "snow-rat": {"n":"Snow Rat","a":"ratfolk","x":"You have a thicker coat and bulkier frame to defend against the cold, granting you cold resistance equal to half your level (minimum 1). You treat environmental cold effects as if they were one step less extreme (incredible cold becomes extreme, extreme cold becomes severe, and so on).","b":"PC2"},
  "spellhorn-kobold": {"n":"Spellhorn Kobold","a":"kobold","x":"Since hatching in the vicinity of a powerful source of magic, a trace of it flows through your veins. Choose one common cantrip from the arcane spell list. You can Cast this Spell as an arcane innate spell at will. A cantrip is heightened to a spell rank equal to half your level rounded up. You are trained in the spell attack modifier and spell DC statistics, and your key spellcasting attribute is Charisma.","b":"PC2"},
  "stickytoe-tripkee": {"n":"Stickytoe Tripkee","a":"tripkee","x":"Your hands and feet exude a film that helps them adhere to surfaces. You gain a +2 circumstance bonus to your Fortitude and Reflex DC against attempts to Disarm, Shove, Reposition, or Trip you. When ascending trees, vines, and other foliage, if you roll a success on the Athletics check to Climb, you get a critical success instead.","b":"PC2"},
  "stormtossed-tengu": {"n":"Stormtossed Tengu","a":"tengu","x":"Whether due to a blessing from the god of storms or hatching from your egg during a squall, you are resistant to storms. You gain electricity resistance equal to half your level (minimum 1). You automatically succeed at the flat check to target a Concealed creature if that creature is concealed only by rain or fog.","b":"PC2"},
  "strong-blooded-dwarf": {"n":"Strong-Blooded Dwarf","a":"dwarf","x":"Your blood runs hearty and strong, and you can shake off toxins. You gain poison resistance equal to half your level (minimum 1), and each of your successful saving throws against a poison affliction reduces its stage by 2, or by 1 for a virulent poison. Each critical success against an ongoing poison reduces its stage by 3, or by 2 for a virulent poison.","b":"PC"},
  "strongjaw-kobold": {"n":"Strongjaw Kobold","a":"kobold","x":"Your warren is noted for their powerful jaws and sharp teeth, either to help protect against natural predators or due to reverence of a mighty beast. You gain a jaws unarmed attack that deals 1d6 piercing damage. Your jaws are in the brawling group and have the finesse and unarmed traits.","b":"PC2"},
  "sweetbreath-kholo": {"n":"Sweetbreath Kholo","a":"kholo","x":"You're a striped, pale-furred kholo with oddly pleasant breath, which you can use to entrance your prey. You are trained in Diplomacy (or another skill if you were already trained in Diplomacy). You also gain a +1 circumstance bonus to checks to Make an Impression if the target can smell your breath.","b":"PC2"},
  "taloned-tengu": {"n":"Taloned Tengu","a":"tengu","x":"Your talons are every bit as sharp and strong as your beak. You gain a talons unarmed attack that deals 1d4 slashing damage. Your talons are in the brawling group and have the agile, finesse, unarmed, and versatile P traits.","b":"PC2"},
  "thickskin-tripkee": {"n":"Thickskin Tripkee","a":"tripkee","x":"Your thick leathery skin resembles that of a toad. You gain 8 Hit Points from your ancestry instead of 6. You gain a +1 circumstance bonus to saves against diseases and poisons.","b":"PC2"},
  "tunnel-rat": {"n":"Tunnel Rat","a":"ratfolk","x":"You can easily compress your body and squeeze through gaps. You gain the Quick Squeeze feat as a bonus feat, even if you aren't trained in Acrobatics. Tight spaces not tight enough to require the Squeeze action aren't difficult terrain for you.","b":"PC2"},
  "tunnelflood-kobold": {"n":"Tunnelflood Kobold","a":"kobold","x":"You grew up in a warren crisscrossed by underwater passages, whether natural or excavated, and were influenced by a powerful aquatic entity or being of primal water. You gain a swim Speed of 15 feet.","b":"PC2"},
  "twilight-halfling": {"n":"Twilight Halfling","a":"halfling","x":"Your ancestors performed many secret acts under the concealing cover of dusk, whether for good or ill, and over time they developed the ability to see in twilight beyond even the usual keen sight of halflings. You gain low-light vision.","b":"PC"},
  "umbral-gnome": {"n":"Umbral Gnome","a":"gnome","x":"Whether from a connection to dark or shadowy fey, from the underground gnomes known as drathnelar, or from another source, you can see in complete darkness. You gain darkvision.","b":"PC"},
  "unbreakable-goblin": {"n":"Unbreakable Goblin","a":"goblin","x":"You're able to bounce back from injuries easily due to an exceptionally thick skull, cartilaginous bones, or some other mixed blessing. You gain 10 Hit Points from your ancestry instead of 6. When you fall, reduce the falling damage you take as though you had fallen half the distance.","b":"PC"},
  "unseen-lizardfolk": {"n":"Unseen Lizardfolk","a":"lizardfolk","x":"You can change your skin color to blend in with your surroundings, making minor shifts with a single action and dramatic changes over the course of an hour. When you're in an area where your coloration is roughly similar to the environment (for instance, forest green in a forest), you can use the minor, single-action application of this ability to make localized changes that help you blend into your surroundings, gaining a +2 circumstance bonus to Stealth checks until your surroundings change in coloration or pattern.","b":"PC2"},
  "venomtail-kobold": {"n":"Venomtail Kobold","a":"kobold","x":"Thanks to the proximity of a venomous creature to your warren, you were born with a vestigial spur in your tail that secretes deadly venom. You gain the Tail Toxin action.","b":"PC2"},
  "versatile-human": {"n":"Versatile Human","a":"human","x":"Humanity's versatility and ambition have fueled its ascendance to be the most common ancestry in most nations throughout the world. Select a general feat of your choice for which you meet the prerequisites (as with your ancestry feat, you can select this general feat at any point during character creation).","b":"PC"},
  "vine-leshy": {"n":"Vine Leshy","a":"leshy","x":"Your prehensile vines grant you unmatched skill at climbing. You do not need to have any hands free to Climb. Additionally, if you roll a success on an Athletics check to Climb, you get a critical success instead.","b":"PC"},
  "warmarch-hobgoblin": {"n":"Warmarch Hobgoblin","a":"hobgoblin","x":"You come from a line of wandering mercenaries constantly on the march and scavenging food on the trail. If you fail, but don't critically fail, to Subsist in the wilderness, you can still keep yourself fed with poor meals. When exploring, you can Hustle twice as long before you have to stop.","b":"PC2"},
  "warrenbred-hobgoblin": {"n":"Warrenbred Hobgoblin","a":"hobgoblin","x":"Your ancestors lived underground. Your ears are larger than those of other hobgoblins and sensitive to echoes. While you're underground, when you target an opponent that is Concealed from you or Hidden from you, reduce the DC of the flat check to 3 for a concealed target or 9 for a hidden one. In addition, if you roll a success on an Acrobatics check to Squeeze, you get a critical success instead.","b":"PC2"},
  "wavediver-tengu": {"n":"Wavediver Tengu","a":"tengu","x":"You're one of the rare tengu who can cut through water like a bird through air, and you often lurk in rivers or oceans where few expect you. You gain a swim Speed of 15 feet.","b":"PC2"},
  "wellspring-gnome": {"n":"Wellspring Gnome","a":"gnome","x":"Some other source of magic has a greater hold on you than the primal magic of your fey lineage does. This connection might come from an occult plane or an ancient occult song; a deity, celestial, or fiend; magical effluent left behind by a mage war; or ancient rune magic.\nChoose arcane, divine, or occult. You gain one cantrip from that magical tradition's spell list. You can cast this spell as an innate spell at will, as a spell of your chosen tradition. A cantrip is heightened to a spell rank equal to half your level rounded up. Whenever you gain a primal innate spell from a gnome ancestry feat, change its tradition from primal to your chosen tradition.","b":"PC"},
  "wetlander-lizardfolk": {"n":"Wetlander Lizardfolk","a":"lizardfolk","x":"Your family is descended from the most common lizardfolk heritage, and you are accustomed to aquatic environments. You gain a 15-foot swim Speed.","b":"PC2"},
  "whisper-elf": {"n":"Whisper Elf","a":"elf","x":"Your ears are finely tuned, able to detect even the slightest whispers of sound. You gain a +2 circumstance bonus when using the Seek action to find Hidden or Undetected creatures within 30 feet of you. When you target an opponent that is Concealed from you or hidden from you, reduce the DC of the flat check to 3 for a concealed target or 9 for a hidden one. This benefit doesn't apply if you can't hear or if the creature is incapable of making sound (for example, if it's affected by a Silence spell).","b":"PC"},
  "wildwood-halfling": {"n":"Wildwood Halfling","a":"halfling","x":"You hail from deep within a jungle or forest, and you've learned how to use your small size to wriggle through undergrowth and other obstacles. You ignore any difficult terrain caused by plants and fungi, such as bushes, vines, and undergrowth.","b":"PC"},
  "windweb-tripkee": {"n":"Windweb Tripkee","a":"tripkee","x":"Tough webbing along your hands and toes can slow any fall. As long as you have one hand free, you take no falling damage, regardless of the distance you fall.","b":"PC2"},
  "winter-catfolk": {"n":"Winter Catfolk","a":"catfolk","x":"You have a thick coat of fur that protects you from the cold. You gain cold resistance equal to half your level (minimum 1). You treat environmental cold effects as if they were one step less extreme (incredible cold becomes extreme, extreme cold becomes severe, and so on).","b":"PC2"},
  "winter-kholo": {"n":"Winter Kholo","a":"kholo","x":"You're a hardy kholo covered in thick, tufted fur that makes you able to survive in the harsh winters of the colder territories. You gain cold resistance equal to half your level (minimum 1). You treat environmental cold effects as if they were one step less extreme (incredible cold becomes extreme, extreme cold becomes severe, and so on).","b":"PC2"},
  "winter-orc": {"n":"Winter Orc","a":"orc","x":"Your ancestors survived in cold climates. You become trained in Survival, and you treat environmental cold effects as if they were one step less extreme (incredible cold becomes extreme, extreme cold becomes severe, and so on).","b":"PC"},
  "witch-kholo": {"n":"Witch Kholo","a":"kholo","x":"You're a shaggy, dark-furred kholo capable of making some truly uncanny sounds. You can cast the Figment cantrip as an occult innate spell at will. A cantrip is heightened to a spell rank equal to half your level rounded up. In addition, you gain a +1 circumstance bonus to checks to Create a Diversion and Impersonate when using only your voice.","b":"PC2"},
  "woodland-elf": {"n":"Woodland Elf","a":"elf","x":"You're adapted to life in the forest, the deep jungle, or a similar environment, and you know how to climb trees and use foliage to your advantage. When Climbing trees, vines, and other foliage, you move at half your Speed on a success and at full Speed on a critical success (and you move at full Speed on a success if you have Quick Climb). This doesn't affect you if you're using a climb Speed.\nYou can always use the Take Cover action when you are within forest terrain to gain cover, even if you're not next to an obstacle you can Take Cover behind.","b":"PC"},
  "woodstalker-lizardfolk": {"n":"Woodstalker Lizardfolk","a":"lizardfolk","x":"You move easily through thick forest and jungle, using every branch or bush. You can always use the Take Cover action when in forest or jungle terrain to gain cover, even if you're not next to an obstacle you would normally be able to Take Cover behind. You gain the Terrain Stalker feat, even if you're not trained in Stealth, and you must choose underbrush as your chosen terrain.","b":"PC2"}
};

const PF2E_BACKGROUNDS = {
  "acolyte": {"n":"Acolyte","bo":[["int","wis"],["free"]],"sk":["religion"],"lo":["Scribing Lore"],"ft":["Student of the Canon"],"x":"You spent your early days in a religious monastery or cloister. You may have traveled out into the world to spread the message of your religion or because you cast away the teachings of your faith, but deep down, you'll always carry within you the lessons you learned.","b":"PC"},
  "acrobat": {"n":"Acrobat","bo":[["dex","str"],["free"]],"sk":["acrobatics"],"lo":["Circus Lore"],"ft":["Steady Balance"],"x":"In a circus or on the streets, you earned your pay by performing as an acrobat. You might have turned to adventuring when the money dried up, or simply decided to put your skills to better use.","b":"PC"},
  "amnesiac": {"n":"Amnesiac","bo":[["free"],["free"],["free"]],"sk":[],"lo":[],"x":"Your background is... well... honestly, you can't remember! You might have inklings deep within your mind, undercurrents of unusual emotions or unexpected responses to certain people or situations, but ultimately you don't know who you once were. You might be adventuring specifically to help discover yourself. It's up to you and the GM how to handle the truth of your character's backstory. You could leave it to the GM so it's a secret, work together with the GM, or even choose to leave it undecided until later. In any case, you and your GM should determine a few noteworthy details about your character or their belongings to get the first clues to your past.","ra":"r","b":"PC2"},
  "animal-whisperer": {"n":"Animal Whisperer","bo":[["cha","wis"],["free"]],"sk":["nature"],"lo":[],"ft":["Train Animal"],"x":"You have always felt a connection to animals, and it was only a small leap to learn to train them. As you travel, you continuously encounter different creatures, befriending them along the way.","b":"PC"},
  "artisan": {"n":"Artisan","bo":[["int","str"],["free"]],"sk":["crafting"],"lo":["Guild Lore"],"ft":["Specialty Crafting"],"x":"As an apprentice, you practiced a particular form of building or crafting, developing a specialized skill. You might have been a blacksmith's apprentice toiling over the forge for countless hours, a young tailor sewing garments of all kinds, or a shipwright shaping the hulls of ships.","b":"PC"},
  "artist": {"n":"Artist","bo":[["cha","dex"],["free"]],"sk":["crafting"],"lo":["Art Lore"],"ft":["Specialty Crafting"],"x":"Your art is your greatest passion, whatever form it takes. Adventuring might help you find inspiration, or simply be a way to survive until you become a world-famous artist.","b":"PC"},
  "astrologer": {"n":"Astrologer","bo":[["int","wis"],["free"]],"sk":["occultism"],"lo":["Astrology Lore"],"ft":["Oddity Identification"],"x":"Astrologers look to the stars for signs and portents, using their positions in the heavens to chart courses for those living beneath them. As the celestial spheres move, so does fate itself. You studied the stars and learned to divine your path based on their guidance. Whether the stars directly called you to a life of adventure or you use the stars to guide your wanderlust, you're living out the stars' guidance in a life of adventure.","b":"PC2"},
  "bandit": {"n":"Bandit","bo":[["cha","dex"],["free"]],"sk":["intimidation"],"lo":[],"ft":["Group Coercion"],"x":"Your past includes no small amount of rural banditry, robbing travelers on the road and scraping by. Whether your robbery was sanctioned by a local noble or you did so of your own accord, you eventually got caught up in the adventuring life.","b":"PC"},
  "barber": {"n":"Barber","bo":[["dex","wis"],["free"]],"sk":["medicine"],"lo":["Surgery Lore"],"ft":["Risky Surgery"],"x":"Haircuts, dentistry, bloodletting, and surgery—if it takes a steady hand and a razor, you can do it. You may have taken to the road to expand your skills or test yourself against a world that leaves your patients so battered and bruised.","b":"PC2"},
  "barkeep": {"n":"Barkeep","bo":[["cha","con"],["free"]],"sk":["diplomacy"],"lo":["Alcohol Lore"],"ft":["Hobnobber"],"x":"You have five specialties: hefting barrels, drinking, polishing steins, drinking, and drinking. You worked in a bar, where you learned how to hold your liquor and rowdily socialize.","b":"PC"},
  "barrister": {"n":"Barrister","bo":[["cha","int"],["free"]],"sk":["diplomacy"],"lo":["Legal Lore"],"ft":["Group Impression"],"x":"Piles of legal manuals, stern teachers, and experience in the courtroom have instructed you in legal matters. You're capable of mounting a prosecution or defense in court, and you tend to keep abreast of local laws, as you never can tell when you might need to know them on short notice.","b":"PC"},
  "blessed": {"n":"Blessed","bo":[["cha","wis"],["free"]],"sk":[],"lo":[],"x":"You have been blessed by a divinity. For an unknown reason, and irrespective of your actual beliefs, a deity has granted you a boon to use for good or ill. Your blessing grants wisdom and insight to aid you in your struggles. You may or may not even know the identity of the being who blessed you, and the blessing might come with a cost you discover later on.","ra":"r","b":"PC2"},
  "bookkeeper": {"n":"Bookkeeper","bo":[["int","wis"],["free"]],"sk":["society"],"lo":["Accounting Lore"],"ft":["Eye For Numbers"],"x":"You ran the numbers on a large farm, for a merchant's endeavors, or with a major guild in the city. You kept track of expenses, payroll, profits, and anything else that had to do with money, for better or worse. If better, you might be adventuring to learn how others ply this trade. If worse, you may be fleeing from impending consequences in the hope that no one finds you.","b":"PC2"},
  "bounty-hunter": {"n":"Bounty Hunter","bo":[["str","wis"],["free"]],"sk":["survival"],"lo":["Legal Lore"],"ft":["Experienced Tracker"],"x":"Bringing in lawbreakers lined your pockets. Maybe you had an altruistic motive and sought to bring in criminals to make the streets safer, or maybe the coin was motivation enough. Your techniques for hunting down criminals transfer easily to the life of an adventurer.","b":"PC"},
  "charlatan": {"n":"Charlatan","bo":[["cha","int"],["free"]],"sk":["deception"],"lo":["Underworld Lore"],"ft":["Charming Liar"],"x":"You traveled from place to place, peddling false fortunes and snake oil in one town, pretending to be royalty in exile to seduce a wealthy heir in the next. Becoming an adventurer might be your next big scam or an attempt to put your talents to use for a greater cause. Perhaps it's a bit of both, as you realize that after pretending to be a hero, you've become the mask.","b":"PC"},
  "cook": {"n":"Cook","bo":[["con","int"],["free"]],"sk":["survival"],"lo":["Cooking Lore"],"ft":["Seasoned"],"x":"You grew up in the kitchens of a tavern or other dining establishment and excelled there, becoming an exceptional cook. Baking, cooking, a little brewing on the side—you've spent lots of time out of sight. It's about time you went out into the world to catch some sights for yourself.","b":"PC"},
  "courier": {"n":"Courier","bo":[["dex","int"],["free"]],"sk":["society"],"lo":[],"ft":["Glean Contents"],"x":"In your youth, you earned coin running messages for persons of wealth and influence, darting through crowded city streets. Your dogged commitment to deliver your message was good training for the life of an adventurer.","b":"PC2"},
  "criminal": {"n":"Criminal","bo":[["dex","int"],["free"]],"sk":["stealth"],"lo":["Underworld Lore"],"ft":["Experienced Smuggler"],"x":"As an unscrupulous independent or as a member of an underworld organization, you lived a life of crime. You might have become an adventurer to seek redemption, to escape the law, or simply to get access to bigger and better loot.","b":"PC"},
  "cultist": {"n":"Cultist","bo":[["cha","int"],["free"]],"sk":["occultism"],"lo":[],"ft":["Schooled In Secrets"],"x":"You were (or still are) a member of a cult whose rites may involve sacred dances to ensure a strong harvest or dire rituals that call upon dark powers. You might have taken up adventuring to further your cult's aims, to initiate yourself into the world's grander mysteries, or to flee unsavory practices or strictures.","b":"PC"},
  "cursed": {"n":"Cursed","bo":[["cha","int"],["free"]],"sk":["occultism"],"lo":["Curse Lore"],"x":"You are the victim of a personal or hereditary curse. Through great effort and occult study, you have learned to fend off the curse's worst effects and, by extension, you can protect yourself against other harmful magic. However, the curse still hangs over you and sometimes manifests in dangerous ways.","ra":"r","b":"PC2"},
  "detective": {"n":"Detective","bo":[["int","wis"],["free"]],"sk":["society"],"lo":["Underworld Lore"],"ft":["Streetwise"],"x":"You solved crimes as a police inspector or took jobs for wealthy clients as a private investigator. You might have become an adventurer as part of your next big mystery, but likely it was due to the consequences or aftermath of a prior case.","b":"PC"},
  "emissary": {"n":"Emissary","bo":[["cha","int"],["free"]],"sk":["society"],"lo":[],"ft":["Multilingual"],"x":"As a diplomat or messenger, you traveled to lands far and wide. Communicating with new people and forming alliances were your stock and trade.","b":"PC"},
  "entertainer": {"n":"Entertainer","bo":[["cha","dex"],["free"]],"sk":["performance"],"lo":["Theater Lore"],"ft":["Fascinating Performance"],"x":"Through an education in the arts or sheer dogged practice, you learned to entertain crowds. You might have been an actor, a dancer, a musician, a street magician, or any other sort of performer.","b":"PC"},
  "farmhand": {"n":"Farmhand","bo":[["con","wis"],["free"]],"sk":["athletics"],"lo":["Farming Lore"],"x":"With a strong back and an understanding of seasonal cycles, you tilled the land and tended crops. Your farm could have been razed by invaders, you could have lost the family tying you to the land, or you might have simply tired of the drudgery, but at some point, you became an adventurer.","b":"PC"},
  "feral-child": {"n":"Feral Child","bo":[["con","dex","str"]],"sk":["nature","survival"],"lo":[],"ft":["Forager"],"x":"You spent your youth in the wilderness, living close to or perhaps raised by animals. You have a close, mystical connection with these animals and gained certain abilities from them, though this limited your well-roundedness in mental pursuits.","ra":"r","b":"PC2"},
  "feybound": {"n":"Feybound","bo":[["cha","dex"],["free"]],"sk":[],"lo":["Fey Lore"],"x":"You have spent time in the First World or another realm of the fey and aren't entirely the same person you were before. Perhaps you made a purchase at the legendary Witchmarket or partook deeply of fey food and wine. Whatever the case, willingly or inadvertently, you made a bargain with the fey, the benefits of which come at a price.","ra":"r","b":"PC2"},
  "field-medic": {"n":"Field Medic","bo":[["con","wis"],["free"]],"sk":["medicine"],"lo":["Warfare Lore"],"ft":["Battle Medicine"],"x":"In the chaotic rush of battle, you learned to adapt to rapidly changing conditions as you administered to battle casualties. You patched up soldiers, guards, or other combatants, and learned a fair amount about the logistics of war.","b":"PC"},
  "fortune-teller": {"n":"Fortune Teller","bo":[["cha","int"],["free"]],"sk":["occultism"],"lo":["Fortune-Telling Lore"],"ft":["Oddity Identification"],"x":"The strands of fate are clear to you, as you have learned many traditional forms by which laypeople can divine the future. You might have used these skills to guide your community, or simply to make money. But even the slightest peek into these practices connects you to the occult mysteries of the universe.","b":"PC"},
  "gambler": {"n":"Gambler","bo":[["cha","dex"],["free"]],"sk":["deception"],"lo":["Games Lore"],"ft":["Lie To Me"],"x":"The thrill of the win drew you into games of chance. This might have been a lucrative sideline that paled in comparison to the real risks of adventuring, or you might have fallen on hard times due to your gambling and pursued adventuring as a way out of a spiral.","b":"PC"},
  "gladiator": {"n":"Gladiator","bo":[["cha","str"],["free"]],"sk":["performance"],"lo":["Gladatorial Lore"],"ft":["Impressive Performance"],"x":"The bloody games of the arena taught you the art of combat. Before you attained true fame, you departed—or escaped—the arena to explore the world. Your skill at drawing both blood and a crowd's attention pay off in a new adventuring life.","b":"PC"},
  "guard": {"n":"Guard","bo":[["cha","str"],["free"]],"sk":["intimidation"],"lo":[],"ft":["Quick Coercion"],"x":"You served in the guard, out of either patriotism or the need for coin. Either way, you know how to get a difficult suspect to talk. However you left the guard, you might think of adventuring as a way to use your skills on a wider stage.","b":"PC"},
  "haunted": {"n":"Haunted","bo":[["cha","wis"],["free"]],"sk":["occultism"],"lo":[],"x":"You are followed by a spirit or entity, either from childhood or since a momentous event. You and others may have seen this entity. You have studied esoteric subjects trying to understand your situation, but this presence in your life remains a mystery. Whatever this entity is or wants, it influences your life in subtle ways, and not always for the better. Sometimes the entity helps you, but at other times, its influence is malevolent or harmful. The entity is most likely to surface in stressful situations.","ra":"r","b":"PC2"},
  "herbalist": {"n":"Herbalist","bo":[["con","wis"],["free"]],"sk":["nature"],"lo":["Herbalism Lore"],"ft":["Natural Medicine"],"x":"As a formally trained apothecary or a rural practitioner of folk medicine, you learned the healing properties of various herbs. You're adept at collecting the right natural cures in all sorts of environments and preparing them properly.","b":"PC"},
  "hermit": {"n":"Hermit","bo":[["con","int"],["free"]],"sk":[],"lo":[],"ft":["Dubious Knowledge"],"x":"In an isolated place—like a cave, remote oasis, or secluded mansion—you lived a life of solitude. Adventuring might be a welcome reprieve from solitude or an unwanted change, but in either case, you're likely still rough around the edges.","b":"PC"},
  "hunter": {"n":"Hunter","bo":[["dex","wis"],["free"]],"sk":["survival"],"lo":["Tanning Lore"],"ft":["Survey Wildlife"],"x":"You stalked and took down animals and other creatures of the wild. Skinning animals, harvesting their flesh, and cooking them were also part of your training, all of which can give you useful resources while you adventure.","b":"PC"},
  "insurgent": {"n":"Insurgent","bo":[["str","wis"],["free"]],"sk":["deception"],"lo":["Warfare Lore"],"ft":["Lengthy Diversion"],"x":"You were more than a rebel; you were a revolutionary, fighting for the promise of a new or better country. You may or may not still believe in the cause, or perhaps victory or exile has led you on this new journey to trumpet your glory... or to escape the consequences of your defeat.","b":"PC2"},
  "laborer": {"n":"Laborer","bo":[["con","str"],["free"]],"sk":["athletics"],"lo":["Labor Lore"],"ft":["Hefty Hauler"],"x":"You've spent years performing arduous physical labor. It was a difficult life, but you somehow survived. You may have embraced adventuring as an easier method to make your way in the world, or you might adventure under someone else's command.","b":"PC"},
  "martial-disciple": {"n":"Martial Disciple","bo":[["dex","str"],["free"]],"sk":[],"lo":["Warfare Lore"],"x":"You dedicated yourself to intense training and rigorous study to become a great warrior. The school you attended might have been a traditionalist monastery, an elite military academy, or the local branch of a prestigious mercenary organization.","b":"PC"},
  "merchant": {"n":"Merchant","bo":[["cha","int"],["free"]],"sk":["diplomacy"],"lo":["Mercantile Lore"],"ft":["Bargain Hunter"],"x":"In a dusty shop, market stall, or merchant caravan, you bartered wares for coin and trade goods. The skills you picked up still apply in the adventuring life, in which a good deal on a suit of armor could prevent your death.","b":"PC"},
  "miner": {"n":"Miner","bo":[["str","wis"],["free"]],"sk":["survival"],"lo":["Mining Lore"],"ft":["Terrain Expertise"],"x":"You earned a living wrenching precious minerals from the lightless depths of the earth. Adventuring might have seemed lucrative or glamorous compared to this backbreaking labor—and if you have to head back underground, this time you plan to do so armed with a real weapon instead of a miner's pick.","b":"PC"},
  "noble": {"n":"Noble","bo":[["cha","int"],["free"]],"sk":["society"],"lo":[],"ft":["Courtly Graces"],"x":"To the common folk, the life of a noble seems one of idyllic luxury, but growing up as a noble or member of the aspiring gentry, you know the reality: a noble's lot is obligation and intrigue. Whether you seek to escape your duties by adventuring or to better your station, you have traded silks and pageantry for an adventurer's life.","b":"PC"},
  "nomad": {"n":"Nomad","bo":[["con","wis"],["free"]],"sk":["survival"],"lo":[],"x":"Traveling far and wide, you picked up basic tactics for surviving on the road and in unknown lands, getting by with few supplies and even fewer comforts. As an adventurer, you travel still, often into even more dangerous places.","b":"PC"},
  "outrider": {"n":"Outrider","bo":[["con","wis"],["free"]],"sk":["nature"],"lo":["Plains Lore"],"ft":["Express Rider"],"x":"In your youth, you galloped on horseback over vast prairies, serving as a vanguard for your settlement, an army, or another group. Seeing so many different lands built a thirst in you to adventure and explore the world instead of just racing past it.","b":"PC2"},
  "pilgrim": {"n":"Pilgrim","bo":[["cha","wis"],["free"]],"sk":["religion"],"lo":[],"ft":["Pilgrim's Token"],"x":"In your youth, you made several pilgrimages to important shrines and sacred sites. You might have been a mendicant friar, a seller of religious relics (real or fraudulent), or just a simple farmer following the dictates of your faith. Whatever the aims of your wanderings now, your faith still protects you on the road.","b":"PC2"},
  "prisoner": {"n":"Prisoner","bo":[["con","str"],["free"]],"sk":["stealth"],"lo":["Underworld Lore"],"ft":["Experienced Smuggler"],"x":"You have been imprisoned or punished for crimes (whether you were guilty or not). Now that your sentence has ended or you've escaped, you take full advantage of the newfound freedom of your adventuring life.","b":"PC"},
  "raised-by-belief": {"n":"Raised by Belief","bo":[["free"],["free"]],"sk":[],"lo":[],"ft":["Assurance"],"x":"Whether in a monastery, a religious household, or just as part of your everyday life, your upbringing was steeped in the traditions of a particular deity. You might remain committed or you may have turned from your childhood creed, but your skills are still founded in your devotion.","b":"PC"},
  "refugee": {"n":"Refugee","bo":[["con","wis"],["free"]],"sk":["society"],"lo":[],"ft":["Streetwise"],"x":"You come from a land very distant from the one you now find yourself in, driven by war, plague, or simply in the pursuit of opportunity. Regardless of your origin or the reason you left your home, you find yourself an outsider in this new land. Adventuring is a way to support yourself while offering hope to those who need it most.","b":"PC2"},
  "returned": {"n":"Returned","bo":[["con","wis"],["free"]],"sk":[],"lo":["Boneyard Lore"],"ft":["Diehard","Additional Lore"],"x":"You died and miraculously returned with knowledge of the realms beyond death and a stronger link to life. Some dead and undead souls might feel a strange, instinctual kinship with you.","ra":"r","b":"PC2"},
  "root-worker": {"n":"Root Worker","bo":[["int","wis"],["free"]],"sk":["occultism"],"lo":["Herbalism Lore"],"ft":["Root Magic"],"x":"Some ailments can't be cured by herbs alone. You learned ritual remedies as well, calling on nature spirits to soothe aches and ward off the evil eye. Taking up with adventurers has given you company on the road, as well as protection from those who would brand you a fake—or worse.","b":"PC2"},
  "royalty": {"n":"Royalty","bo":[["cha","int"],["free"]],"sk":["society"],"lo":[],"ft":["Courtly Graces"],"x":"You are a prominent member of a royal family. You have eschewed the daily routines of royal life and taken up an adventurous quest—perhaps you're a deposed queen hoping to regain her throne, a prince seeking a more exciting life, or a sovereign's heir on a secret mission.","ra":"r","b":"PC2"},
  "saboteur": {"n":"Saboteur","bo":[["dex","str"],["free"]],"sk":["thievery"],"lo":["Engineering Lore"],"ft":["Concealing Legerdemain"],"x":"Whether you do it for personal enjoyment or at the behest of a mercenary company or military organization, you have a knack for destroying things. You have a sense for an object or structure's weak spots and know where to deliver a hammer strike or alchemical bomb. You adventure to hone your skills or complete a particular mission.","b":"PC2"},
  "sailor": {"n":"Sailor","bo":[["dex","str"],["free"]],"sk":["athletics"],"lo":["Sailing Lore"],"ft":["Underwater Marauder"],"x":"You heard the call of the sea from a young age. Perhaps you signed onto a merchant's vessel, joined the navy, or even fell in with a crew of pirates and scalawags.","b":"PC"},
  "scavenger": {"n":"Scavenger","bo":[["int","wis"],["free"]],"sk":["survival"],"lo":[],"ft":["Forager"],"x":"You've made a living sorting through the things society throws away. You might have scavenged simply to survive, or plied a trade as a ragpicker, dung carter, or the like. While you've left that life behind, you still keep one eye on the ground out of habit.","b":"PC2"},
  "scholar": {"n":"Scholar","bo":[["int","wis"],["free"]],"sk":[],"lo":["Academia Lore"],"x":"You have a knack for learning and sequestered yourself from the outside world to learn all you could. You read about so many wondrous places and things in your books, always dreaming about one day seeing the real things. Eventually, that curiosity led you to leave your studies and become an adventurer.","b":"PC"},
  "scout": {"n":"Scout","bo":[["dex","wis"],["free"]],"sk":["survival"],"lo":[],"ft":["Forager"],"x":"You called the wilderness home as you found trails and guided travelers. Your wanderlust could have called you to the adventuring life, or perhaps you served as a scout for soldiers and found you liked battle.","b":"PC"},
  "servant": {"n":"Servant","bo":[["cha","dex"],["free"]],"sk":["society"],"lo":["Labor Lore"],"ft":["Read Lips"],"x":"You held a role of servitude, waiting on nobles and engendering their trust as one of the confidantes of the household. You might have walked away on good terms, or perhaps you know dangerous secrets about your former employers. Regardless, you're adventuring for a change and finding that in this new role, the skills you've learned now serve you.","b":"PC2"},
  "squire": {"n":"Squire","bo":[["con","str"],["free"]],"sk":["athletics"],"lo":[],"ft":["Armor Assist"],"x":"You trained at the feet of a knight, maintaining their gear and supporting them at tourneys and in battle. Now you search for a challenge that will prove you worthy of full knighthood, or you've spurned pomp and ceremony to test yourself in honest, albeit less formal, combat.","b":"PC2"},
  "street-urchin": {"n":"Street Urchin","bo":[["con","dex"],["free"]],"sk":["thievery"],"lo":[],"ft":["Pickpocket"],"x":"You eked out a living by picking pockets on the streets of a major city, never knowing where you'd find your next meal. While some adventure for the glory, you do so to survive.","b":"PC"},
  "tax-collector": {"n":"Tax Collector","bo":[["cha","str"],["free"]],"sk":["intimidation"],"lo":[],"ft":["Quick Coercion"],"x":"Reviled but required, you were sent when taxes were due. Performing your job might have required travel and persuasion, or perhaps you were responsible for collecting taxes on trade. Either way, it sometimes meant dirty hands, and adventuring seemed the next logical step to you.","b":"PC2"},
  "teacher": {"n":"Teacher","bo":[["int","wis"],["free"]],"sk":[],"lo":["Academia Lore"],"ft":["Experienced Professional"],"x":"You are incredibly knowledgeable, skilled, and perhaps even trained to teach children and adults about the world and its wonders. From books to classes, you're committed to imparting knowledge to all. Not everything can be taught or learned from a book, though, so you've become an adventurer to learn subjects more directly and bring that wisdom back to your students.","b":"PC"},
  "tinker": {"n":"Tinker","bo":[["dex","int"],["free"]],"sk":["crafting"],"lo":["Engineering Lore"],"ft":["Specialty Crafting"],"x":"Creating all sorts of minor inventions scratches your itch for problem-solving. Your engineering skills take a particularly creative bent, and no one know what you'll come up with next. It might be a genius device with tremendous potential or it might explode.","b":"PC"},
  "ward": {"n":"Ward","bo":[["cha","con"],["free"]],"sk":["performance"],"lo":["Genealogy Lore"],"ft":["Fascinating Performance"],"x":"When you were young, you became the ward of another house—boarded, fed, and educated, but never quite a part of the family. Perhaps you had to tend to their needs in return for feeding and raising you, or perhaps you were provided for but disregarded. Now, adventuring is your chance to grow and roam free.","b":"PC2"},
  "warrior": {"n":"Warrior","bo":[["con","str"],["free"]],"sk":["intimidation"],"lo":["Warfare Lore"],"ft":["Intimidating Glare"],"x":"In your younger days, you waded into battle as a mercenary, a warrior defending a nomadic people, or a member of a militia or army. You might have wanted to break away from the regimented structure of these forces, or you could have always been as independent a warrior as you are now.","b":"PC"}
};

